def _parse_money(value: str) -> Decimal:
    """The dollar amount on a line.

    The amount is the first figure in the value; notes often follow it
    ("$100.00 (1 extra stop)", "$75.00/hr after 2 hrs free"), so the last
    number on the line is not reliable.
    """
    amounts = _MONEY.findall(value) or _NUMBER.findall(value)
    if not amounts:
        raise RateConError(f"no amount in {value!r}")
    return Decimal(amounts[0].replace(",", ""))

def _bridge_spans(axle_count: int, tandems: set[int]) -> list[tuple[int, int]]:
    """Every group of two or more consecutive axles, except a lone tandem.

    A group that is just one tandem is covered by the tandem limit instead.
    """
    return [
        (first, last)
        for first in range(axle_count)
        for last in range(first + 1, axle_count)
        if not (last - first == 1 and first in tandems)
    ]

